values
  ('4ce4a930-99e9-5632-b027-7a899abe1f66', null, (select id from public.skills where slug = 'read-g8-evidence-inference'), null, 'hard',
   $q$Based on the passage, which noise would noise-canceling headphones handle LEAST well?$q$, $q$[{"text":"The rumble of a bus engine while it waits at a stop","is_correct":false,"misconception_token":"misapplies-detail"},{"text":"The clapping and cheering at a school assembly","is_correct":true},{"text":"The low hum of a refrigerator in a quiet kitchen","is_correct":false,"misconception_token":"misapplies-detail"},{"text":"The steady drone of train wheels on a long trip","is_correct":false,"misconception_token":"misapplies-detail"}]$q$::jsonb, $q$The clapping and cheering at a school assembly$q$, $q$Clapping and cheering are sudden and high, the kind of sounds the passage says "change too quickly" to cancel. The refrigerator, train and bus all make steady, low sounds, which the passage says the headphones handle best.$q$, 'draft', '5926b490-2222-522a-9061-0bf4c852108e')
