  ('93d7cb9d-cce2-573c-b75b-cd040ca16de3', null, (select id from public.skills where slug = 'read-g8-evidence-inference'), null, 'medium',
   $q$Based on the passage, which plan would best count as active recovery the day after a hard game?$q$, $q$[{"text":"A full day on the couch without moving at all","is_correct":false,"misconception_token":"misapplies-concept"},{"text":"A slow walk around the park followed by gentle stretching","is_correct":true},{"text":"A timed set of all-out sprints on the track","is_correct":false,"misconception_token":"misapplies-concept"},{"text":"A weight workout with heavier weights than usual","is_correct":false,"misconception_token":"misapplies-concept"}]$q$::jsonb, $q$A slow walk around the park followed by gentle stretching$q$, $q$The passage describes active recovery as easy activity that keeps blood flowing "without adding much strain," like a slow swim or gentle stretching. A day on the couch is rest, but the passage says active recovery is different from "lying on the couch."$q$, 'draft', 'c4cb6e84-5cb9-5608-acfd-145dea8d4e7f')
