  ('4e78fda9-4ee4-579c-9108-aab22cde0e6b', null, (select id from public.skills where slug = 'read-g8-story-details-inference'), null, 'easy',
   $q$Based on the passage, what did Mr. Okafor most likely do with the purple beans he borrowed last spring?$q$, $q$[{"text":"He planted them and saved seeds from the plants he grew.","is_correct":true},{"text":"He gave the whole packet to the rabbits in his yard.","is_correct":false,"misconception_token":"literal-reading"},{"text":"He bought new bean seeds at a store to replace them.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"He returned the same packet without ever planting it.","is_correct":false,"misconception_token":"contradicts-text"}]$q$::jsonb, $q$He planted them and saved seeds from the plants he grew.$q$, $q$His envelopes say "SAVED FROM ROW TWO," which shows he grew the beans and collected new seeds from them. He returns twenty envelopes, not the single packet he took, so he did not simply give it back unused.$q$, 'draft', '35357fc7-92f2-58cf-871e-db790e0345a0')
