values
  ('9a798acc-c3be-518a-ab63-354e3cea2e4f', null, (select id from public.skills where slug = 'read-g8-story-details-inference'), null, 'hard',
   $q$Which detail best supports the inference that Tamsin's thinking has changed by the end of the fable?$q$, $q$[{"text":"She carries ten acorns to the hillside and pushes them into the soil.","is_correct":true},{"text":"She lands beside the nearest shoot and tilts her head at it.","is_correct":false,"misconception_token":"partial-evidence"},{"text":"She gathers her acorns and counts them twice, as she always has.","is_correct":false,"misconception_token":"weak-evidence"},{"text":"She eats her acorns carefully, one row at a time, through winter.","is_correct":false,"misconception_token":"wrong-sequence"}]$q$::jsonb, $q$She carries ten acorns to the hillside and pushes them into the soil.$q$, $q$Earlier Tamsin called burying acorns "a waste of good food," so planting some herself shows a real change. Tilting her head shows curiosity, but it does not yet show that she acts differently.$q$, 'draft', '391e7083-ed94-521f-a6b6-1693679227c9')
