-- Passage rg8-story-details-inference-p04
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('db2a0d11-cac3-5ea6-a6d9-fb0dd68d1645', 'rg8-story-details-inference-p04', (select id from public.skills where slug = 'read-g8-story-details-inference'), null,
        '6-8', $q$Drift$q$, $q$Mateo had rebuilt the robot's left wheel three times, and it still drifted. On the practice table in the school gym, the little machine rolled forward, wobbled, and curved toward the wall as if something were pulling it.

"It's the motor," Mateo said. He was already reaching for the screwdriver.

Hana did not answer. She was watching the patch of afternoon light that fell through the high gym windows and stretched across one corner of the table. She set the robot back at the starting line and pressed the button again. This time she held a clipboard above the robot so that its shadow covered the light sensor on top.

The robot rolled straight to the end of the table and stopped exactly on the black finish line.

Mateo lowered the screwdriver. "Do that again."

She did, four more times. With the clipboard, the robot drove straight every time. Without it, the robot curved toward the bright corner every time.

"The competition is at nine in the morning," Hana said. "In a different gym."

Mateo looked at his notebook, where he had written WHEEL in capital letters and underlined it twice. He crossed it out. Then he opened the laptop and began adjusting the number that told the sensor how much light to expect.

Coach Bergstrom walked past, glanced at the clipboard, and smiled without saying a word.$q$, 'draft')
