-- Passage rg8-theme-summary-p08
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('a5f31ae2-6566-59e3-b405-513670ea7e35', 'rg8-theme-summary-p08', (select id from public.skills where slug = 'read-g8-theme-summary'), null,
        '6-8', $q$The Mockingbird Who Lost Her Song$q$, $q$In a meadow at the edge of a pine forest lived a young mockingbird named Wren. She had a song of her own, a bright tumbling tune that rose and fell like water over pebbles. But Wren noticed that the other birds praised it only politely.

So Wren began to listen. She copied the cardinal's clear whistle, and the cardinal said it was charming. She copied the jay's sharp call, and the jays laughed with delight. She learned the owl's low hoot, the finch's chatter, and the creak of the old gate by the farmhouse. Every bird in the meadow wanted to hear her imitate someone.

By midsummer, Wren could sing any song in the forest. One evening, a small finch who had hatched that spring hopped onto her branch.

"Which song is yours?" he asked.

Wren opened her beak to answer. She tried to find the tumbling tune she had sung in spring, but all that came out was the cardinal's whistle, then the jay's call, then the creak of the gate. Her own song was buried under all the others.

For many days, Wren sat alone in the oldest pine and sang quietly to herself. She sang badly at first, and some notes were wrong. Slowly the tumbling tune came back, a little different now, with a few of the finch's notes folded inside it.

When she finally sang it from the top of the pine, the meadow went quiet. The young finch was the first to answer, singing it back to her as well as he could.$q$, 'draft')
